class BloomFilter:
    """
    A Bloom filter implementation using a bit array and multiple hash functions.

    The size of the bit array and the number of hash functions are calculated 
    based on the expected number of items and the desired false positive rate.
    Uses simple hashing via hashlib to create the hash values.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.m = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.k = self._optimal_number_of_hash_functions(expected_items, self.m)
        self.bit_array = [0] * self.m

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self, n: int, m: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate multiple hash values for the given item."""
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.m for i in range(self.k)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for hash_val in self._hashes(item):
            self.bit_array[hash_val] = 1

    def contains(self, item: str) -> bool:
        """Check if the item may be present in the Bloom filter."""
        return all(self.bit_array[hash_val] for hash_val in self._hashes(item))
